// Parse the AI Agent output
let aiOutput = $input.all()[0].json.output;

// Remove markdown code blocks if present
aiOutput = aiOutput.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();

// Parse the JSON string to an object
const parsedData = JSON.parse(aiOutput);

// Return the parsed data
return [{ json: parsedData }];

// Combine all data sources into table_11 structured format
const unreadPapers = $('Get Unread Papers').all();
const calendarEvents = $('Check Calendar for Scholarships').all();
const emails = $('Get Scholarship Emails').all();

const output = {
  unread_papers: unreadPapers.map(p => ({
    title: p.json.title,
    authors: p.json.authors,
    date: p.json.publication_date,
    url: p.json.url,
    abstract: p.json.abstract?.substring(0, 200) + '...'
  })),
 calendar_events: calendarEvents.map(e => ({
    summary: e.json.summary,
    start: e.json.start?.dateTime || e.json.start?.date,
    description: e.json.description
   })),
   scholarship_emails: emails.map(email => ({
     subject: email.json.subject,
     from: email.json.from,
     snippet: email.json.snippet,
     date: email.json.date,
     id: email.json.id
   })),
   generated_at: new Date().toISOString(),
   total_unread: unreadPapers.length
};

return [{ json: output }];

