const input = $input.first().json.chatInput.trim().toLowerCase();
const nameParts = input.split(/\s+/).filter(p => p.length > 0);

if (nameParts.length === 0) {
  throw new Error('No name provided');
}

// Strategy: Use PostgreSQL regex to match the name in sequence
// "valerie ward" -> matches "Valerie Ward", "Valerie C. A. Ward", "V. Ward", etc.
// But won't match "Indiana Ward" as "valerie ward"
const regexPattern = nameParts.join('[^,]*\\s+'); // valerie[^,]*\s+ward
// This matches: valerie followed by any non-comma characters, then space, then ward

const query = `
SELECT * FROM table_2 
WHERE authors::text ~* '${regexPattern}[^,]*'
ORDER BY publication_date DESC;
`;

return {
  query: query,
  professor_name: input,
  original_input: $input.first().json.chatInput,
  regex_pattern: regexPattern
};

// Get the output string
const output = $input.first().json.output;

// Split by 'body: ' to separate subject and body
const parts = output.split('body: ');

// Extract subject (remove 'subject: ' prefix and trim)
const subject = parts[0].replace('subject: ', '').trim();

// Extract body (everything after 'body: ')
const body = parts[1].trim();

// Return structured data for Gmail node
return [
  {
    json: {
      subject: subject,
      body: body
    }
  }
];
